script:
(function () {
  'use strict';

  function $(id) { return document.getElementById(id); }

  var btnStartTest = $('btnStartTest');
  var btnHeardIt = $('btnHeardIt');
  var btnStopTest = $('btnStopTest');
  var trialReadout = $('trialReadout');
  var trialProgressFill = $('trialProgressFill');
  var diagnosticPanel = $('diagnosticPanel');
  var statEstimate = $('statEstimate');
  var statHardware = $('statHardware');
  var statReaction = $('statReaction');
  var statAudioReaction = $('statAudioReaction');
  var statWireless = $('statWireless');
  var infoRating = $('infoRating');
  var infoBpm = $('infoBpm');
  var infoBeatMs = $('infoBeatMs');
  var infoModulo = $('infoModulo');
  var infoDetectedBpm = $('infoDetectedBpm');
  var selectMethod = $('selectMethod');
  var methodHint = $('methodHint');
  var bpmField = $('bpmField');
  var beatBpm = $('beatBpm');
  var flashBox = $('flashBox');
  var sliderField = $('sliderField');
  var flashDelaySlider = $('flashDelaySlider');
  var flashDelayValue = $('flashDelayValue');
  var wiredBaseline = $('wiredBaseline');
  var btnUseBaseline = $('btnUseBaseline');

  var ROUNDS = 5; // per phase: 5 flash taps, then 5 beep taps
  var MAX_GAIN = 0.4;
  var FLASH_ON = '#7c5cff';

  var audioCtx = null;
  var running = false;
  var method = 'two_phase';
  var phase = 'flash';          // two_phase: 'flash' -> 'beep'
  var trialIndex = 0;
  var flashResults = [];
  var beepResults = [];
  var stimulusTime = null;
  var waitingForTap = false;
  var timers = [];
  var missTimer = null;
  var lastLatency = null;
  // Beat / slider methods
  var schedTimer = null;
  var nextBeatTime = 0;
  var beatPeriod = 0.6;
  var firstBeatPerf = null;
  var tapTimes = [];
  var tapOffsets = [];

  flashBox.style.transition = 'none'; // the stimulus must appear in one frame, not fade in

  function setDiagnostic(sev, html) {
    diagnosticPanel.innerHTML = '<div class="diagnostic-item' + (sev ? ' sev-' + sev : '') + '"><span class="diag-icon" aria-hidden="true">' +
      '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
      '</span><span>' + html + '</span></div>';
  }

  function show(el, on) { el.classList.toggle('u-hidden', !on); }

  function later(fn, ms) { var id = setTimeout(fn, ms); timers.push(id); return id; }
  function clearTimers() { timers.forEach(clearTimeout); timers = []; }

  function ensureContext() {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    return audioCtx.resume().catch(function () {});
  }

  function reportHardwareLatency() {
    if (!audioCtx) return;
    var parts = [];
    if (typeof audioCtx.baseLatency === 'number') parts.push('base ' + Math.round(audioCtx.baseLatency * 1000) + ' ms');
    if (typeof audioCtx.outputLatency === 'number') parts.push('output ' + Math.round(audioCtx.outputLatency * 1000) + ' ms');
    statHardware.textContent = parts.length ? parts.join(', ') : 'Not reported';
  }

  // Short tone at an audio-clock time `when` (defaults to now).
  function tone(freq, when, dur) {
    var osc = audioCtx.createOscillator();
    var gain = audioCtx.createGain();
    osc.type = 'sine';
    osc.frequency.value = freq;
    gain.gain.value = 0;
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    var t = when || audioCtx.currentTime;
    gain.gain.setValueAtTime(0, t);
    gain.gain.linearRampToValueAtTime(MAX_GAIN, t + 0.005);
    gain.gain.setValueAtTime(MAX_GAIN, t + dur - 0.03);
    gain.gain.linearRampToValueAtTime(0, t + dur);
    osc.start(t);
    osc.stop(t + dur + 0.02);
    osc.onended = function () { try { osc.disconnect(); gain.disconnect(); } catch (e) {} };
  }

  // Converts an audio-clock time to the performance.now() clock, using the
  // browser's own output timestamp where available.
  function perfTimeOf(ctxTime) {
    if (audioCtx.getOutputTimestamp) {
      var ts = audioCtx.getOutputTimestamp();
      if (ts && ts.performanceTime) return ts.performanceTime + (ctxTime - ts.contextTime) * 1000;
    }
    return performance.now() + (ctxTime - audioCtx.currentTime) * 1000;
  }

  function flash(on, text) {
    flashBox.style.backgroundColor = on ? FLASH_ON : '';
    flashBox.style.color = on ? '#fff' : '';
    flashBox.textContent = text || (on ? 'TAP' : '');
  }

  function rateLatency(ms) {
    if (ms < 20) return 'Under 20 ms: fine for everything, including live instruments and monitoring';
    if (ms < 40) return '20–40 ms: good for competitive gaming';
    if (ms < 100) return '40–100 ms: fine for video and calls; lip-sync starts to show near the top';
    if (ms < 200) return '100–200 ms: fine for music and most video';
    return '200 ms or more: music listening only';
  }

  function showLatency(ms, extra) {
    lastLatency = ms;
    statEstimate.textContent = Math.round(ms) + ' ms' + (extra || '');
    infoRating.textContent = rateLatency(Math.max(0, ms));
    btnUseBaseline.disabled = false;
    updateWireless();
  }

  function updateWireless() {
    var base = parseFloat(wiredBaseline.value);
    if (lastLatency == null || !isFinite(base)) { statWireless.textContent = '—'; return; }
    statWireless.textContent = Math.round(lastLatency - base) + ' ms';
  }

  // ---- Two-phase method: flash taps, then beep taps -------------------------
  function cleanTaps(arr) {
    var v = arr.filter(function (x) { return x > 80 && x < 1200; }).sort(function (a, b) { return a - b; });
    if (v.length < 3) return v;
    var med = v[Math.floor(v.length / 2)];
    return v.filter(function (x) { return Math.abs(x - med) < Math.max(80, med * 0.4); });
  }
  function mean(a) { return a.reduce(function (s, x) { return s + x; }, 0) / a.length; }
  function sd(a) { var m = mean(a); return Math.sqrt(a.reduce(function (s, x) { return s + (x - m) * (x - m); }, 0) / Math.max(1, a.length - 1)); }

  function scheduleTrial() {
    trialIndex++;
    var total = ROUNDS * 2;
    var n = (phase === 'beep' ? ROUNDS : 0) + trialIndex;
    trialReadout.textContent = (phase === 'flash' ? 'Flash ' : 'Beep ') + trialIndex + ' of ' + ROUNDS + ' (trial ' + n + ' of ' + total + ')';
    trialProgressFill.style.width = Math.round((n - 1) / total * 100) + '%';
    btnHeardIt.textContent = phase === 'flash' ? 'Tap on the Flash!' : 'I Heard It!';
    setDiagnostic('', phase === 'flash' ? 'Watch the box and tap the instant it flashes…' : 'Listen and tap the instant you hear the beep…');
    // Random 1-3s wait before each stimulus so the visitor can't anticipate
    // the exact timing, per this tool's own spec note.
    later(function () {
      if (!running) return;
      if (phase === 'flash') {
        requestAnimationFrame(function () {
          if (!running) return;
          flash(true);
          stimulusTime = performance.now();
          armTap();
          later(function () { flash(false); }, 180);
        });
      } else {
        reportHardwareLatency();
        var t = audioCtx.currentTime + 0.05;
        tone(880, t, 0.18);
        stimulusTime = perfTimeOf(t);
        armTap();
      }
    }, 1000 + Math.random() * 2000);
  }

  function armTap() {
    waitingForTap = true;
    btnHeardIt.disabled = false;
    // A trial with no tap within 1.5s is treated as missed and discarded
    // rather than left hanging indefinitely.
    if (missTimer) clearTimeout(missTimer);
    missTimer = later(function () {
      if (waitingForTap) {
        waitingForTap = false;
        btnHeardIt.disabled = true;
        nextTrial();
      }
    }, 1500);
  }

  function nextTrial() {
    if (!running) return;
    if (trialIndex >= ROUNDS) {
      if (phase === 'flash') {
        phase = 'beep';
        trialIndex = 0;
        var f = cleanTaps(flashResults);
        statReaction.textContent = f.length ? mean(f).toFixed(1) + ' ms' : '—';
        scheduleTrial();
      } else {
        finishTwoPhase();
      }
    } else {
      scheduleTrial();
    }
  }

  function finishTwoPhase() {
    stopRun();
    trialProgressFill.style.width = '100%';
    btnStartTest.textContent = 'Run Test Again';
    var f = cleanTaps(flashResults), b = cleanTaps(beepResults);
    statReaction.textContent = f.length ? mean(f).toFixed(1) + ' ms' : '—';
    statAudioReaction.textContent = b.length ? mean(b).toFixed(1) + ' ms' : '—';
    if (f.length < 3 || b.length < 3) {
      setDiagnostic('warn', '<strong>Not enough valid taps to estimate.</strong> Try again and tap as soon as you see each flash or hear each beep.');
      statEstimate.textContent = 'Inconclusive';
      return;
    }
    var lat = mean(b) - mean(f);
    var ci = 1.96 * Math.sqrt(sd(f) * sd(f) / f.length + sd(b) * sd(b) / b.length);
    showLatency(lat, ' ± ' + Math.round(ci));
    setDiagnostic('ok', '<strong>Estimated audio latency: ' + Math.round(lat) + ' ms (± ' + Math.round(ci) + ' ms).</strong> Beep average ' + mean(b).toFixed(1) + ' ms minus flash average ' + mean(f).toFixed(1) + ' ms, from ' + b.length + ' beep and ' + f.length + ' flash taps after dropping outliers. Includes your display’s own delay, so compare devices on the same screen.');
  }

  // ---- Direct method 1: tap along to a beat ---------------------------------
  function readBpm() {
    var bpm = parseFloat(beatBpm.value);
    if (!isFinite(bpm)) bpm = 100;
    return Math.max(60, Math.min(300, bpm));
  }

  function beatScheduler() {
    while (nextBeatTime < audioCtx.currentTime + 0.12) {
      tone(1000, nextBeatTime, 0.05);
      if (firstBeatPerf == null) firstBeatPerf = perfTimeOf(nextBeatTime);
      nextBeatTime += beatPeriod;
    }
  }

  function startBeat() {
    var bpm = readBpm();
    beatPeriod = 60 / bpm;
    firstBeatPerf = null;
    tapTimes = [];
    tapOffsets = [];
    nextBeatTime = audioCtx.currentTime + 0.3;
    infoBpm.textContent = String(bpm);
    infoBeatMs.textContent = Math.round(beatPeriod * 1000) + ' ms';
    infoModulo.textContent = '—';
    infoDetectedBpm.textContent = '—';
    schedTimer = setInterval(beatScheduler, 25);
    beatScheduler();
    btnHeardIt.textContent = 'Tap on the Beat';
    btnHeardIt.disabled = false;
    trialReadout.textContent = 'Tap along with the clicks';
    setDiagnostic('', 'Tap the button in time with each click. After 8 or more taps the trailing average of how far your taps land behind the beat is your latency reading.');
  }

  function beatTap(now) {
    if (firstBeatPerf == null) return;
    var p = beatPeriod * 1000;
    var mod = ((now - firstBeatPerf) % p + p) % p;
    var offset = mod > p / 2 ? mod - p : mod;
    tapTimes.push(now);
    tapOffsets.push(offset);
    if (tapTimes.length > 16) tapTimes.shift();
    if (tapOffsets.length > 8) tapOffsets.shift();
    infoModulo.textContent = Math.round(mod) + ' ms';
    if (tapTimes.length >= 3) {
      var gaps = [];
      for (var i = 1; i < tapTimes.length; i++) gaps.push(tapTimes[i] - tapTimes[i - 1]);
      infoDetectedBpm.textContent = (60000 / mean(gaps)).toFixed(1);
    }
    trialReadout.textContent = tapOffsets.length + ' taps';
    trialProgressFill.style.width = Math.min(100, tapOffsets.length / 8 * 100) + '%';
    if (tapOffsets.length >= 4) showLatency(mean(tapOffsets), ' (trailing avg)');
  }

  // ---- Direct method 2: flash-delay slider ----------------------------------
  // A click plays on a repeating one-second cycle and the box flashes with
  // the slider's delay; when they feel simultaneous the slider value is
  // the audio output latency relative to the display.
  function sliderCycle() {
    if (!running || method !== 'slider') return;
    var t = audioCtx.currentTime + 0.15;
    tone(1000, t, 0.05);
    var flashAt = perfTimeOf(t) + parseFloat(flashDelaySlider.value);
    later(function () {
      requestAnimationFrame(function () {
        if (!running) return;
        flash(true, ' ');
        later(function () { flash(false, ' '); }, 90);
      });
    }, Math.max(0, flashAt - performance.now() - 8));
    later(sliderCycle, 1000);
  }

  function startSlider() {
    btnHeardIt.disabled = true;
    trialReadout.textContent = 'Adjust the slider until flash and click feel simultaneous';
    setDiagnostic('', 'Watch the box and listen. Drag <strong>Flash delay</strong> until the flash and the click feel exactly simultaneous; the value is your audio latency.');
    showLatency(parseFloat(flashDelaySlider.value), ' (slider)');
    sliderCycle();
  }

  // ---- Run control ----------------------------------------------------------
  function stopRun() {
    running = false;
    waitingForTap = false;
    clearTimers();
    if (schedTimer) { clearInterval(schedTimer); schedTimer = null; }
    flash(false, 'Ready');
    btnHeardIt.disabled = true;
    btnStopTest.disabled = true;
    btnStartTest.disabled = false;
    selectMethod.disabled = false;
  }

  function startTest() {
    if (running) return;
    method = selectMethod.value;
    ensureContext().then(function () {
      reportHardwareLatency();
      running = true;
      btnStartTest.disabled = true;
      btnStartTest.textContent = 'Testing…';
      btnStopTest.disabled = false;
      selectMethod.disabled = true;
      trialProgressFill.style.width = '0%';
      if (method === 'beat') startBeat();
      else if (method === 'slider') startSlider();
      else {
        phase = 'flash';
        trialIndex = 0;
        flashResults = [];
        beepResults = [];
        statReaction.textContent = '—';
        statAudioReaction.textContent = '—';
        flash(false, '');
        scheduleTrial();
      }
    });
  }

  function applyMethodUi() {
    var m = selectMethod.value;
    show(bpmField, m === 'beat');
    show(sliderField, m === 'slider');
    methodHint.textContent = m === 'beat' ? 'Tap along to a steady click; the trailing average of how late your taps land is the delay'
      : m === 'slider' ? 'A click and a flash repeat every second — slide the flash delay until they line up'
      : 'Tap when the box flashes (5 rounds), then tap when you hear the beep (5 rounds)';
    trialReadout.textContent = m === 'two_phase' ? 'Trial 0 of ' + (ROUNDS * 2) : 'Not started';
    btnHeardIt.textContent = m === 'beat' ? 'Tap on the Beat' : 'I Heard It!';
  }

  btnStartTest.addEventListener('click', startTest);
  btnStopTest.addEventListener('click', function () {
    stopRun();
    btnStartTest.textContent = 'Start Test';
    setDiagnostic('', 'Stopped.');
  });
  btnHeardIt.addEventListener('click', function () {
    var now = performance.now();
    if (!running) return;
    if (method === 'beat') { beatTap(now); return; }
    if (!waitingForTap) return;
    waitingForTap = false;
    if (missTimer) { clearTimeout(missTimer); missTimer = null; }
    var reaction = now - stimulusTime;
    (phase === 'flash' ? flashResults : beepResults).push(reaction);
    btnHeardIt.disabled = true;
    nextTrial();
  });
  selectMethod.addEventListener('change', applyMethodUi);
  beatBpm.addEventListener('change', function () {
    var bpm = readBpm();
    infoBpm.textContent = String(bpm);
    infoBeatMs.textContent = Math.round(60000 / bpm) + ' ms';
    if (running && method === 'beat') { beatPeriod = 60 / bpm; firstBeatPerf = null; nextBeatTime = audioCtx.currentTime + 0.2; tapOffsets = []; tapTimes = []; }
  });
  flashDelaySlider.addEventListener('input', function () {
    flashDelayValue.textContent = flashDelaySlider.value + ' ms';
    if (running && method === 'slider') showLatency(parseFloat(flashDelaySlider.value), ' (slider)');
  });
  wiredBaseline.addEventListener('input', updateWireless);
  btnUseBaseline.addEventListener('click', function () {
    if (lastLatency == null) return;
    wiredBaseline.value = String(Math.round(lastLatency));
    updateWireless();
  });

  window.addEventListener('pagehide', function () {
    stopRun();
    if (audioCtx) { audioCtx.close().catch(function () {}); audioCtx = null; }
  });
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden' && running) {
      stopRun();
      btnStartTest.textContent = 'Start Test';
      setDiagnostic('warn', 'Test stopped because the page was hidden. Start again when ready.');
    }
  });

  applyMethodUi();

  if (!(window.AudioContext || window.webkitAudioContext)) {
    setDiagnostic('error', '<strong>Your browser doesn’t support the Web Audio API.</strong>');
    btnStartTest.disabled = true;
  }
})();
